import {RAWL_COLORS} from './rawl-colors.mjs';
import {brickNameHTML} from './brick-labels.js';
import {mountRawlView,bindHarmonyHover} from './rawl-view.js';
import {createPlayer,bindTempoKeys} from './audio-player.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=pause=>`<svg viewBox="0 0 24 24" aria-hidden="true">${pause?'<path d="M10 4H6v16h4zM18 4h-4v16h4z"/>':'<path d="m8 5 11 7-11 7V5Z"/>'}</svg>`;
export async function mountAtlas(root){
 const destroyHarmony=bindHarmonyHover(document);
 const response=await fetch('./data/atlas.json');if(!response.ok)throw Error(response.status);const data=await response.json(),cadences=await fetch('./data/cadences.json').then(response=>response.json()),items=data.groups.flatMap(g=>g.bricks),comparisons=data.comparisons??[],cards=new Map(),comparisonCards=[];let active=null;
 const comparisonHTML=comparisons.length?`<section class="brick-comparisons" id="compare"><h2>Compare</h2><div class="comparison-viewport"><div class="comparison-stack" style="width:${Math.max(...comparisons.map(b=>(b.offsetBars+b.performance.beats/b.performance.barBeats)*b.measureWidth))}px">${comparisons.map(b=>`<article class="comparison-card" data-comparison="${esc(b.id)}" data-variant="${esc(b.variantId)}" style="margin-left:${b.offsetBars*b.measureWidth}px;width:${b.performance.beats/b.performance.barBeats*b.measureWidth}px"><div class="atlas-card-head"><button class="atlas-play" aria-label="Play" title="Play">${icon(false)}</button><h3><a href="./index.html#brick/${b.slug}?variant=${b.variantId}">${brickNameHTML(b.name,b)}</a></h3></div><div class="atlas-preview comparison-preview" aria-label="Rawl notation"></div><span class="atlas-error" hidden>Playback error</span></article>`).join('')}</div></div></section>`:'';
 root.innerHTML=`<h1>Bricks<span class="atlas-total">${items.length}</span></h1><nav class="atlas-index" aria-label="Groups"><a href="#cadences">Cadences</a>${comparisons.length?'<a href="#compare">Compare</a>':''}${data.groups.map((group,i)=>`<a href="#type-${i}">${brickNameHTML(group.type)}</a>`).join('')}</nav><section class="cadence-system" id="cadences"><h2>Cadences</h2><div class="cadence-matrix"></div><details class="cadence-generalized"><summary>Generalized</summary><div class="cadence-matrix"></div></details></section>${comparisonHTML}<div class="atlas-groups">${data.groups.map((g,i)=>`<section class="atlas-group" style="width:${Math.max(330,...g.bricks.map(b=>b.performance.beats/b.performance.barBeats*100))}px" data-type="${esc(g.type)}" aria-labelledby="type-${i}"><h2 id="type-${i}">${brickNameHTML(g.type)} <span>${g.bricks.length}</span></h2>${g.bricks.map(b=>`<article class="atlas-card" id="${b.slug}" data-brick="${b.slug}"><div class="atlas-card-head"><button class="atlas-play" aria-label="Play" title="Play">${icon(false)}</button><h3><a href="./index.html#brick/${b.slug}">${brickNameHTML(b.name,b)}</a></h3><a class="atlas-card-count" href="./index.html#brick/${b.slug}" title="Standards">${b.standards}</a></div><div class="atlas-preview" aria-label="Rawl notation"></div><span class="atlas-error" hidden>Playback error</span></article>`).join('')}</section>`).join('')}</div>`;
 const roots=['I','♭II','II','♭III','III','IV','♭V','V','♭VI','VI','♭VII','VII'];
 const degree=(text,root)=>`<span data-degree="${root}" style="color:${RAWL_COLORS[root].background}">${esc(text)}</span>`;
 const matchesHTML=matches=>{const seen=new Set();return matches.filter(match=>{if(seen.has(match.slug))return false;seen.add(match.slug);return true;}).map(match=>{const brick=items.find(item=>item.slug===match.slug);return `<a href="./index.html#brick/${match.slug}?variant=${match.variantId}">${brickNameHTML(brick?.name??match.name,brick)}</a>`;}).join(', ')||'—';};
 root.querySelector('#cadences>.cadence-matrix').innerHTML=cadences.rows.map(row=>`<div class="cadence-pattern" data-scheme-row="${row.row}"><div class="cadence-pattern-rn"><span class="cadence-pattern-number">${String(row.row).padStart(2,'0')}</span>${row.roots.map((root,i)=>degree((i%2?roots[root]:roots[root].toLowerCase())+'7',root)).join('<span class="cadence-separator">–</span>')}<span class="cadence-separator">→</span>${degree('I',0)}</div><div class="cadence-pattern-bricks">${matchesHTML(row.matches)}</div></div>`).join('');
 root.querySelector('.cadence-generalized .cadence-matrix').innerHTML=cadences.generalized.map(group=>`<div class="cadence-pattern"><div class="cadence-pattern-rn">${group.matches[0].roots.map((root,i)=>degree((i%2?roots[root]:roots[root].toLowerCase())+(group.qualities[i]==='half-diminished'?'ø7':group.qualities[i]==='minor'?'':'7'),root)).join('<span class="cadence-separator">–</span>')}<span class="cadence-separator">→</span>${degree('I',0)}</div><div class="cadence-pattern-bricks">${matchesHTML(group.matches)}</div></div>`).join('');
 const player=createPlayer({onState:state=>{
  if(!active)return;const running=state==='playing',label=running?'Pause':state==='loading'?'Loading':'Play';active.button.innerHTML=icon(running);active.button.setAttribute('aria-label',label);active.button.title=label;active.button.setAttribute('aria-busy',String(state==='loading'));active.error.hidden=state!=='error';
 },onPosition:beat=>active?.view.setPosition(beat),onError:error=>{console.error(error);if(active)active.error.hidden=false;}});
 function activate(card){if(active===card)return;player.stop();active=card;player.load(card.item.performance);}
 function mountCard(item,element){
  const button=element.querySelector('.atlas-play'),card={item,element,button,error:element.querySelector('.atlas-error')};
  card.view=mountRawlView(element.querySelector('.atlas-preview'),{song:item.performance.previewSong,performance:item.performance,brickMap:new Map([[item.name,item]]),compact:true,continuous:true,measureWidth:100,mutedVoices:[],onSeek:beat=>{activate(card);player.seek(beat);},onNote:note=>player.audition(note)});
  button.onclick=()=>{activate(card);void player.toggle();};return card;
 }
 for(const item of items)cards.set(item.slug,mountCard(item,root.querySelector(`[data-brick="${item.slug}"]`)));
 for(const item of comparisons)comparisonCards.push(mountCard(item,root.querySelector(`[data-comparison="${item.id}"]`)));
 const unbindTempo=bindTempoKeys({adjustTempo:delta=>{if(!active)return false;player.setTempo(player.tempo+delta*active.item.performance.tempo);}});
 let destroyed=false;const destroy=()=>{if(destroyed)return;destroyed=true;unbindTempo();player.destroy();destroyHarmony();for(const card of [...cards.values(),...comparisonCards])card.view.destroy();window.removeEventListener('beforeunload',destroy);};window.addEventListener('beforeunload',destroy,{once:true});
 if(location.hash)requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView({block:'start'}));
 return {cards,comparisonCards,player,destroy};
}
export const ready=mountAtlas(document.querySelector('#atlas')).catch(error=>{console.error(error);document.querySelector('.atlas-loading').textContent='Unavailable';});
